def check_password(username: str, password: str) -> bool:
stored = USERS.get(username)
try:
ph.verify(stored or DUMMY_HASH, password) # same work if user is unknown
except (VerificationError, InvalidHashError):
return False
if stored is None:
return False
if ph.check_needs_rehash(stored): # parameters were raised
USERS[username] = ph.hash(password)
return True
def too_many_failures(username: str) -> bool:
now = time.time()
recent = [t for t in FAILS.get(username, []) if now - t < FAIL_WINDOW]
FAILS[username] = recent
return len(recent) >= MAX_FAILS
